<script setup lang="ts">import{reactive,ref,onMounted,onUnmounted}from'vue';import{api,errorMessage}from'../api';import PageHeader from'../components/PageHeader.vue';import Modal from'../components/Modal.vue';import StatusBadge from'../components/StatusBadge.vue';import{Plus,PlugZap,Activity}from'lucide-vue-next';const catalog=ref<any[]>([]),items=ref<any[]>([]),open=ref(false),error=ref('');const form=reactive({plugin_key:'repository',name:'',priority:100,configText:'{}',secretsText:'{}'});async function load(){[catalog.value,items.value]=await Promise.all([api.get('/plugins/catalog').then(r=>r.data),api.get('/plugins/installations').then(r=>r.data)])}async function save(){try{await api.post('/plugins/installations',{plugin_key:form.plugin_key,name:form.name,priority:form.priority,config:JSON.parse(form.configText),secrets:JSON.parse(form.secretsText)});open.value=false;await load()}catch(e){error.value=errorMessage(e)}}async function health(id:string){await api.post(`/plugins/installations/${id}/healthcheck`);await load()}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))</script><template><PageHeader title="Plugins e conectores" subtitle="Instale fontes, provedores, armazenamentos e automações sem alterar o núcleo"><button class="btn primary" @click="open=true"><Plus :size="16"/>Instalar plugin</button></PageHeader><div class="plugin-grid"><article v-for="item in items" :key="item.id" class="plugin-card"><div class="plugin-icon"><PlugZap/></div><div class="plugin-head"><div><h3>{{item.name}}</h3><small>{{item.plugin_key}}</small></div><StatusBadge :status="item.health_status"/></div><div class="plugin-meta"><span>Prioridade <b>{{item.priority}}</b></span><span>Ativo <b>{{item.enabled?'Sim':'Não'}}</b></span></div><button class="btn small" @click="health(item.id)"><Activity :size="15"/>Testar conexão</button></article><div v-if="!items.length" class="panel empty-state"><h3>Nenhum plugin instalado</h3><p>Instale o repositório, uma API HTTP, fonte simulada ou portal assistido.</p></div></div><Modal :open="open" title="Instalar plugin" wide @close="open=false"><form class="form-grid" @submit.prevent="save"><label>Plugin<select v-model="form.plugin_key"><option v-for="p in catalog" :value="p.key">{{p.name}}</option></select></label><label>Nome da instalação<input v-model="form.name" required/></label><label>Prioridade<input v-model.number="form.priority" type="number" min="1"/></label><label class="span-2">Configuração JSON<textarea v-model="form.configText" rows="7"></textarea></label><label class="span-2">Segredos JSON<textarea v-model="form.secretsText" rows="5"></textarea></label><div v-if="error" class="alert danger span-2">{{error}}</div><div class="form-actions span-2"><button class="btn primary">Instalar</button></div></form></Modal></template>
